# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">SAHABENİN PEYGAMBERİMİZE (S.A.V.) SEVGİ, SAYGI VE İTAATİ (2.4)</text>\n  <rect x="20" y="45" width="210" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Canından Çok Sevme</text>\n  <text x="32" y="92" font-size="10.5" font-weight="bold" fill="#1d4ed8">• "Anam babam sana feda olsun!"</text>\n  <text x="40" y="108" font-size="10" fill="#1e3a8a">(فِدَاكَ أَبِي وَأُمِّي يَا رَسُولَ اللّٰهِ)</text>\n  <text x="32" y="130" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Hz. Ömer Hadisi:</tspan> İmanın</text>\n  <text x="40" y="146" font-size="10" fill="#1e3a8a">kemali, Resulullah\'ı kendi nefsinden</text>\n  <text x="40" y="162" font-size="10" fill="#1e3a8a">ve ailesinden çok sevmektir.</text>\n  <text x="32" y="184" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Fedakârlık:</tspan> Hz. Ali\'nin yatağa</text>\n  <text x="40" y="200" font-size="10" fill="#1e3a8a">yatması, Uhud\'da Hz. Talha ve</text>\n  <text x="40" y="216" font-size="10" fill="#1e3a8a">Nesîbe Hatun\'un kalkan olması.</text>\n  <rect x="245" y="45" width="210" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Gönülden İtaat ve Edep</text>\n  <text x="257" y="92" font-size="10.5" font-weight="bold" fill="#15803d">• "İşittik ve İtaat Ettik!"</text>\n  <text x="265" y="108" font-size="10" fill="#14532d">(سَمِعْنَا وَأَطَعْنَا — Bakara, 2/285)</text>\n  <text x="257" y="130" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Hucurât Suresi Edebi:</tspan></text>\n  <text x="265" y="146" font-size="10" fill="#14532d">Peygamber\'in önüne geçmemek,</text>\n  <text x="265" y="162" font-size="10" fill="#14532d">sesini onun sesinin üstüne</text>\n  <text x="265" y="178" font-size="10" fill="#14532d">yükseltmemek (Sabit b. Kays).</text>\n  <text x="257" y="200" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Hudeybiye\'de Rıdvan Biatı:</tspan></text>\n  <text x="265" y="216" font-size="10" fill="#14532d">Ölüm üzerine tam sadakat sözü.</text>\n  <rect x="470" y="45" width="210" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. İtaat - Vahiy Dengesi</text>\n  <text x="482" y="92" font-size="10.5" font-weight="bold" fill="#b45309">• Vahiy ile İstişare Ayrımı:</text>\n  <text x="490" y="108" font-size="10" fill="#78350f">Sahabe, emrin vahiy mi yoksa</text>\n  <text x="490" y="124" font-size="10" fill="#78350f">dünyevi/askeri tedbir mi olduğunu</text>\n  <text x="490" y="140" font-size="10" fill="#78350f">edep çerçevesinde sorardı.</text>\n  <text x="482" y="162" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Bedir\'de Hubâb b. Münzir:</tspan></text>\n  <text x="490" y="178" font-size="10" fill="#78350f">Kuyuların yeri konusunda görüşü.</text>\n  <text x="482" y="200" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Hendek\'te Selmân-ı Fârisî:</tspan></text>\n  <text x="490" y="216" font-size="10" fill="#78350f">Hendek kazılması teklifi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">SAHABENİN SÜNNETİ YAŞAMA HASSASİYETİ VE ÖRNEK ŞAHSİYETLER</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Sünneti Hayat tarzı Edinme</text>\n  <text x="40" y="94" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Kıble Değişikliği (Kıbleteyn):</tspan> Namaz</text>\n  <text x="48" y="110" font-size="10" fill="#1e3a8a">esnasında gelen emirle anında Kâbe\'ye yöneliş.</text>\n  <text x="40" y="132" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Mescid-i Nebevî\'de İnfak ve Zühd:</tspan></text>\n  <text x="48" y="148" font-size="10" fill="#1e3a8a">Ebû Talha\'nın en sevdiği Beyruhâ bahçesini</text>\n  <text x="48" y="164" font-size="10" fill="#1e3a8a">Allah yolunda bağışlaması (Âl-i İmrân, 3/92).</text>\n  <text x="40" y="186" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Abdullah b. Ömer (r.a.):</tspan> Hz. Peygamber\'in</text>\n  <text x="48" y="202" font-size="10" fill="#1e3a8a">sünnetini en ince ayrıntısına kadar yaşama</text>\n  <text x="48" y="218" font-size="10" fill="#1e3a8a">konusunda sahabenin en titiz örneklerinden biridir.</text>\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Bilinçli Takip ve İstikamet</text>\n  <text x="380" y="94" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Hz. Ebû Bekir (r.a.):</tspan> "Resulullah\'ın</text>\n  <text x="388" y="110" font-size="10" fill="#14532d">uyguladığı hiçbir sünneti terk etmem; terk</text>\n  <text x="388" y="126" font-size="10" fill="#14532d">edersem hak yoldan sapmaktan korkarım."</text>\n  <text x="380" y="148" font-size="10.5" fill="#14532d">• <tspan font-weight="bold">Muâz b. Cebel (r.a.) — Yemen Görevi:</tspan></text>\n  <text x="388" y="164" font-size="10" fill="#14532d">1. Allah\'ın Kitabı (Kur\'an) ile hükmederim,</text>\n  <text x="388" y="180" font-size="10" fill="#14532d">2. Resulullah\'ın Sünneti ile hükmederim,</text>\n  <text x="388" y="196" font-size="10" fill="#14532d">3. İkisinde bulamazsam kendi re\'yimle içtihat</text>\n  <text x="388" y="212" font-size="10" font-weight="bold" fill="#166534">ederim (Sünnetin teşrîdeki 2. kaynak oluşu).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">SÜNNETİN KORUNMASI VE SONRAKİ NESİLLERE AKTARILMASI (MÜKSİRÛN)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Sünneti Öğrenme ve Aktarma Yöntemleri</text>\n  <text x="35" y="94" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Nöbetleşe İlim Takibi:</tspan> Hz. Ömer\'in</text>\n  <text x="43" y="110" font-size="10" fill="#78350f">Ensar\'dan komşusuyla nöbetleşerek Resulullah\'ın</text>\n  <text x="43" y="126" font-size="10" fill="#78350f">meclisine katılması ve öğrendiklerini paylaşması.</text>\n  <text x="35" y="148" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Hadis Yazımı (Sahîfeler):</tspan> Abdullah b. Amr</text>\n  <text x="43" y="164" font-size="10" fill="#78350f">b. Âs\'ın <tspan font-weight="bold">es-Sahîfetü\'s-Sâdıka</tspan>\'sı ve Hemmâm</text>\n  <text x="43" y="180" font-size="10" fill="#78350f">b. Münebbih\'in sahîfesi.</text>\n  <text x="35" y="202" font-size="10.5" fill="#78350f">• <tspan font-weight="bold">Er-Rıhle fî Talebi\'l-İlm:</tspan> Tek bir hadisi</text>\n  <text x="43" y="218" font-size="10" fill="#78350f">bizzat kaynağından duymak için yapılan yolculuklar.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">En Çok Hadis Rivayet Edenler (Müksirûn)</text>\n  <text x="375" y="92" font-size="10.5" fill="#581c87">Binden fazla hadis rivayet eden <tspan font-weight="bold">7 sahabi</tspan>:</text>\n  <text x="383" y="112" font-size="10.5" font-weight="bold" fill="#7e22ce">1. Ebû Hüreyre (r.a.) — 5374 hadis</text>\n  <text x="383" y="130" font-size="10.5" fill="#581c87">2. Abdullah b. Ömer (r.a.) — 2630 hadis</text>\n  <text x="383" y="148" font-size="10.5" fill="#581c87">3. Enes b. Mâlik (r.a.) — 2286 hadis</text>\n  <text x="383" y="166" font-size="10.5" font-weight="bold" fill="#7e22ce">4. Hz. Âişe (r.anhâ) — 2210 hadis</text>\n  <text x="383" y="184" font-size="10.5" fill="#581c87">5. Abdullah b. Abbâs (r.a.) — 1660 hadis</text>\n  <text x="383" y="202" font-size="10.5" fill="#581c87">6. Câbir b. Abdullah (r.a.) — 1540 hadis</text>\n  <text x="383" y="220" font-size="10.5" fill="#581c87">7. Ebû Saîd el-Hudrî (r.a.) — 1170 hadis</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
